WITH uni AS (
  SELECT UNNEST(['6920','6146','6857','7011','8035','5803','8306','9984','7203','9983','8316','7013','6758','6501','7012','7974','8411','6861','6098','6526','4063','9501','8058','8136','8766','7267','9432','6723','9101','8031','9104','8001','4568','7735','6367','9433','7741','2914','4755','6981','4502','6503','7003','6702','9107','4519','6273','6954','6762','6701','6594','3382','6902','4661','8725','7751','5401','6301','1605','7201','8002','5801','7936','9434','6315','6752','8801','7269','9843','5108','4062','8308','6525','8604','4901','7453','8802','8630','8750','7182','8053','8591','4503','7014','4385','7270','2502','5020','4543','6178','5802','4452','4911','8267','3350','4578','3436','3498','7733','8309','2802','6506','7832','9020','9022','9503','6988','8473','6971','1928','6963','7261','5411','1925','3778','3697','6326','5713','3099','8830','4307','9766','6361','4523','2413','8015','5253','7532','9697','6504','9201','4689','6871','1911','7272','5838','6532','4507','7309','2432','9531','6976','2503','8113','8601','5631','6645','3659','8795','1801','1802','6383','9735','3563','9202','1812','9021','4004','7202','8697','4704','5406','4684','7259','3402','6323','3038','3092','4188','4751','3407','9509','6590','5201','5019','3064','4005','9502','2768','4528','9684','2801','2897','7211','6479','4324','6869','1803','6305','2267','7911','9532','2875','7550','2269','1878','5334','6586','5332','9024','6141','5344','3088','4183','9602','7729','3197','7186','6965','4204','6254','8593','4612','8354','9147','8331','9009','9508','3003','7752','3231','2587','5831','4768','7912','4021','9962','2160','6841','7181','3086','6724','3349','9064','7701','4186','6324','7731','3110','3861','4151','4091','5105','9506','9005','3289','6481','3994','7747','3626','8233','6460','4107','8304','5706','3769','9435','8804','3405','4506','5938','6448','9041','5021','6856','2702','8253','8227','5101','6465','4042','5032','5711','9143','7276','6370','6417','5929','6113','4680','6806','6368','9042','4527','4592','6740','4922','7951','2282','4182','9142','6728','7167','4980','2871','4536','8252','9166','5844','4732']) AS sym, '大型' AS grp
  UNION ALL SELECT UNNEST(['6727','2353','7433','6490','8276','4028','3101','3612','4813','6619','3193','3191','7224','9424','7047','4633','6810','3482','3093','8346','4588','9832','1898','7630','7381','7516','7283','9678','6498','9090','6454','3475','5911','6588','4493','7685','7352','6240','8544','8771','8923','9882','3222','3205','6458','4882','7821','3002','1952','7776','4575','3903','6516','4825','135A','3431','4547','9075','6817','7864','6997','8361','3844','8850','8370','3608','3148','8609','6430','1720','7239','4499','1515','8386','7033','8715','3793','3989','3315','4985','5027','3103','9743','9716','5208','6958','8237','9830','7734','9828','5331','9517','4432','9211','3880','4419','6209','9746','4344','6183','8011','6652','8061','9551','3106','8218','1852','6929','4343','4431','3856','7944','9715','6331','9025','4044','1934','6947','5988','3443','4187','6058','8934','8153','6834','3433','7241','3663','6750','1766','5254','8337','7970','6866','4549','8336','4928','6744','5302','8613','4461','8051','3252','3915','4966','7915','6376','3496','7130','5132','6914','7715','8200','2590','2884','7412','4417','3167','5715','2281','5408','8706','2124','3561','8057','3034','9956','6999','3299','9511','6363','7184','9267','1941','9889','7575','7094','3656','6226','7366','9948','6250','9757','6330','6523','4914','6638','4216','2484','4011','4095','6264','7613','9413','9997','5602','7777','2918','5930','7976','4563','6768','8614','6859','1882','6332','7246','6474','1835','9436','8892','5262','7717','9887','7943','7860','7995','6625','8707','8160','9556','2491','6547','3558','6677','4078','3864','9960','2384','8214','3028','6203','8278','3245','4694','3179','9158','8388','5440','8097','7287','1968','8133','7711','8338','9268','3679','4784','5975','9204','9974','9869','2998','7595','6737','2216','7981','8704','3632','9037','8550','3565','4293','7965','6143','1975','2752','5949','6779','7803','6191','8360','6521','2471','7456','6387','2749','3854','8125','6298','2733','8566','7979','4099','8173','7513','3486','6145','4425','4047','2330','3984','9274','4221','5943','4889','6284','5243','9692','3091']), '中小型'
),
bars AS (
  SELECT b.symbol || '0' AS Code, u.grp, CAST(b.date AS DATE) d, b.open o, b.close c, b.volume v
  FROM read_parquet('data/bars/*.parquet') b JOIN uni u ON u.sym = b.symbol
  WHERE b.open > 0
),
b2 AS (
  SELECT *, LEAD(c, 4) OVER w c5, LEAD(c, 9) OVER w c10, LEAD(c, 19) OVER w c20,
    AVG(v) OVER (PARTITION BY Code ORDER BY d ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) v20
  FROM bars WINDOW w AS (PARTITION BY Code ORDER BY d)
),
fwd0 AS (SELECT Code, grp, d, v20, c, c5/o-1 r5, c10/o-1 r10, c20/o-1 r20 FROM b2 WHERE c20 IS NOT NULL),
fwd AS (
  SELECT *, r5 - AVG(r5) OVER (PARTITION BY grp, d) x5, r10 - AVG(r10) OVER (PARTITION BY grp, d) x10, r20 - AVG(r20) OVER (PARTITION BY grp, d) x20
  FROM fwd0
)
